def stage_timing_path(project: Path) -> Path:
    return project / ".domainry" / "development" / "stages.json"


def load_stage_timing(project: Path) -> dict:
    path = stage_timing_path(project)
    if not path.exists():
        return {"contract_version": STAGE_TIMING_VERSION, "stages": {}}
    if path.is_symlink() or not path.is_file():
        raise GateError("development stage timing state is unsafe")
    raw = json.loads(path.read_text(encoding="utf-8"))
    if raw.get("contract_version") == STAGE_TIMING_VERSION:
        if not isinstance(raw.get("stages"), dict):
            raise GateError("development stage timing state is invalid")
        return raw
    if not isinstance(raw, dict):
        raise GateError("legacy development stage timing state is invalid")
    stages = {}
    for stage, row in raw.items():
        if stage not in STAGE_TIMING_STAGES or not isinstance(row, dict):
            raise GateError("legacy development stage timing state is invalid")
        started = row.get("started")
        ended = row.get("ended")
        if isinstance(started, bool) or not isinstance(started, (int, float)):
            raise GateError("legacy development stage start time is invalid")
        if ended is not None and (isinstance(ended, bool) or not isinstance(ended, (int, float))):
            raise GateError("legacy development stage end time is invalid")
        start_ms = int(started * 1000)
        end_ms = int(ended * 1000) if ended is not None else None
        attempt = {
            "attempt": 1, "kind": "initial", "started_epoch_ms": start_ms,
            "ended_epoch_ms": end_ms,
        }
        if end_ms is not None:
            attempt.update({
                "wall_ms": max(0, end_ms - start_ms), "cli_active_ms": 0,
                "orchestration_idle_ms": max(0, end_ms - start_ms),
            })
        stages[stage] = {"first_started_epoch_ms": start_ms, "attempts": [attempt]}
        if end_ms is not None:
            stages[stage]["first_ended_epoch_ms"] = end_ms
    return {"contract_version": STAGE_TIMING_VERSION, "stages": stages}


def stage_timing_summary(document: dict, observed_epoch_ms: int | None = None) -> dict:
    initial = recovery = active = idle = wall = 0
    attempt_count = 0
    starts = []
    ends = []
    for stage in document["stages"].values():
        for attempt in stage.get("attempts", []):
            attempt_count += 1
            if isinstance(attempt.get("started_epoch_ms"), int):
                starts.append(attempt["started_epoch_ms"])
            if isinstance(attempt.get("ended_epoch_ms"), int):
                ends.append(attempt["ended_epoch_ms"])
            elif isinstance(attempt.get("started_epoch_ms"), int) and observed_epoch_ms is not None:
                ends.append(observed_epoch_ms)
            value = int(attempt.get("wall_ms", 0))
            if (
                attempt.get("ended_epoch_ms") is None
                and isinstance(attempt.get("started_epoch_ms"), int)
                and observed_epoch_ms is not None
            ):
                value = max(0, observed_epoch_ms - attempt["started_epoch_ms"])
            wall += value
            attempt_active = min(value, int(attempt.get("cli_active_ms", 0)))
            active += attempt_active
            idle += int(attempt.get("orchestration_idle_ms", value - attempt_active))
            if attempt.get("kind") == "initial":
                initial += value
            else:
                recovery += value
    outer = document.get("outer_started_epoch_ms")
    total_wall = startup = inter_stage = overlap = None
    boundary_state = "outer_start_unavailable"
    if (
        isinstance(outer, int) and not isinstance(outer, bool)
        and starts and ends and outer <= min(starts)
    ):
        total_wall = max(0, max(ends) - outer)
        startup = max(0, min(starts) - outer)
        inter_stage = max(0, total_wall - startup - wall)
        overlap = max(0, startup + wall - total_wall)
        boundary_state = "complete"
    return {
        "attempt_count": attempt_count, "wall_ms": wall,
        "initial_attempt_wall_ms": initial, "recovery_attempt_wall_ms": recovery,
        "cli_active_ms": active, "agent_orchestration_idle_ms": idle,
        "boundary_state": boundary_state,
        "startup_skill_routing_ms": startup,
        "inter_stage_orchestration_idle_ms": inter_stage,
        "overlapping_stage_wall_ms": overlap,
        "total_orchestration_idle_ms": (
            None if inter_stage is None else idle + inter_stage
        ),
        "total_wall_ms": total_wall,
    }


