def command_stage_open(args, project: Path, session: str) -> int:
    document = load_stage_timing(project)
    if args.outer_started_epoch_ms is not None:
        existing_outer = document.get("outer_started_epoch_ms")
        earliest = min((
            attempt.get("started_epoch_ms")
            for value in document["stages"].values()
            for attempt in value.get("attempts", [])
            if isinstance(attempt.get("started_epoch_ms"), int)
        ), default=int(time.time() * 1000))
        if args.outer_started_epoch_ms <= 0 or args.outer_started_epoch_ms > earliest:
            raise GateError("outer driver start must be a positive epoch no later than the first stage")
        if existing_outer is not None and existing_outer != args.outer_started_epoch_ms:
            raise GateError("outer driver start is immutable once recorded")
        document["outer_started_epoch_ms"] = args.outer_started_epoch_ms
    stage = document["stages"].setdefault(args.stage, {"attempts": []})
    attempts = stage["attempts"]
    if attempts and attempts[-1].get("ended_epoch_ms") is None:
        raise GateError("development stage already has an open attempt")
    started = int(time.time() * 1000)
    kind = args.kind or ("initial" if not attempts else "resume")
    attempt = {
        "attempt": len(attempts) + 1, "kind": kind,
        "started_epoch_ms": started, "ended_epoch_ms": None,
    }
    attempts.append(attempt)
    stage.setdefault("first_started_epoch_ms", started)
    atomic_json(stage_timing_path(project), document)
    print(json.dumps(attempt, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
    return 0


def command_stage_close(args, project: Path, session: str) -> int:
    document = load_stage_timing(project)
    stage = document["stages"].get(args.stage, {})
    attempts = stage.get("attempts", [])
    if not attempts or attempts[-1].get("ended_epoch_ms") is not None:
        raise GateError("development stage has no open attempt")
    attempt = attempts[-1]
    ended = int(time.time() * 1000)
    wall = max(0, ended - attempt["started_epoch_ms"])
    active = min(wall, args.cli_active_ms)
    attempt.update({
        "ended_epoch_ms": ended, "wall_ms": wall, "cli_active_ms": active,
        "orchestration_idle_ms": wall - active,
    })
    stage.setdefault("first_ended_epoch_ms", ended)
    atomic_json(stage_timing_path(project), document)
    output = {"attempt": attempt, "summary": stage_timing_summary(document)}
    print(json.dumps(output, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
    return 0


